            if (property.equals("for")) {
                property = "forValue";
            }
            final Attributes attribute;
            try {
                attribute = Attributes.valueOf(property);
            } catch (final IllegalArgumentException e) {
                Assert.fail(e.getMessage());
            }
        }
    }
}

