    Assert.assertEquals("is at beginning", false, data.isAtBeginning());
    data.setFirst(0);
    // * X X X X X X X X
    Assert.assertEquals("current page", 0, data.getCurrentPage());
    Assert.assertEquals("is at beginning", true, data.isAtBeginning());
    data.setFirst(100);
    // out of range
