@Test
public void testFileNames() {
    final NavigationTree navigation = new NavigationTree() {

        @Override
        protected List<String> locateResourcesInWar(final ServletContext servletContext, final String directory, final List<String> result) {
            return LIST;
        }
    };
    navigation.postConstruct();
    final NavigationNode root = navigation.getTree();
    Assert.assertEquals(2, root.getChildCount());
    final NavigationNode n00 = (NavigationNode) root.getChildAt(0);
    Assert.assertEquals("/content/00", n00.getBranch());
    Assert.assertEquals("test-1", n00.getName());
    final NavigationNode n01 = (NavigationNode) root.getChildAt(1);
    Assert.assertEquals("/content/01", n01.getBranch());
    Assert.assertEquals("test", n01.getName());
    final NavigationNode n0000 = (NavigationNode) n00.getChildAt(0);
    Assert.assertEquals("/content/00/00", n0000.getBranch());
    Assert.assertEquals("test-4", n0000.getName());
    final NavigationNode n0007 = (NavigationNode) n00.getChildAt(1);
    Assert.assertEquals("/content/00/07", n0007.getBranch());
    Assert.assertEquals("test-2", n0007.getName());
}

/**
 * Verify if qunit test for "no exception".
 */
@ParameterizedTest
@MethodSource("verifyNoException404TestProvider")
void verifyNoExceptionTest(Browser browser, String portContextPath) throws MalformedURLException, UnsupportedEncodingException, UnknownHostException {
    LOG.info("browser: " + browser + " - port and context path: " + portContextPath);
    setupBrowser(browser);
    final String path = "error/exception.xhtml";
    setupWebDriver(portContextPath, path, true);
    waitForQUnitBanner();
    WebElement qunitTests = getWebDriver().findElement(By.id("qunit-tests"));
    List<WebElement> results = qunitTests.findElements(By.xpath("li"));
    boolean testException = false;
    for (final WebElement result : results) {
        if ("has no exception".equals(result.findElement(By.className("test-name")).getText())) {
            Assert.assertEquals(result.getAttribute("class"), "fail");
            testException = true;
        }
    }
    Assert.assertTrue("Could not verify 'has no exception' test.", testException);
}

