@Test
public void testNames() throws NoSuchFieldException {
    final String fieldRegex = "[A-Z][A-Z0-9_]*[A-Z0-9]";
    final String nameRegex = "[a-z][a-z0-9\\-]*[a-z0-9]";
    for (final BootstrapClass value : BootstrapClass.values()) {
        final boolean ignoreByTest = BootstrapClass.class.getField(value.name()).isAnnotationPresent(Deprecated.class);
        if (!ignoreByTest) {
            final String field = value.toString();
            final String name = value.getName();
            Assert.assertTrue("testing: '" + field + "' matches regexp for consts like FOO_BAR", field.matches(fieldRegex));
            Assert.assertTrue("testing: '" + name + "' matches regexp for CSS like foo-bar", name.matches(nameRegex));
            final StringBuilder calculatedName = new StringBuilder();
            for (int i = 0; i < field.length(); i++) {
                final char c = field.charAt(i);
                if (c == '_') {
                    calculatedName.append("-");
                } else {
                    calculatedName.append(Character.toLowerCase(c));
                }
            }
            Assert.assertEquals(field, calculatedName.toString(), name);
        }
    }
}

/**
 * This test checks, if every item of the {@link BootstrapClass} occurs in the bootstrap.css.
 */
@Test
public void testCompareBootstrapCss() throws IOException, NoSuchFieldException {
    final BootstrapClass[] allValues = BootstrapClass.values();
    final List<BootstrapClass> toCheck = new ArrayList<>();
    for (final BootstrapClass value : allValues) {
        final boolean ignoreByTest = BootstrapClass.class.getField(value.name()).isAnnotationPresent(Deprecated.class);
        if (!ignoreByTest) {
            toCheck.add(value);
        }
    }
    final List<CssItem> missing = CssClassUtils.compareCss("src/main/resources/META-INF/resources/tobago/standard/tobago-bootstrap/_version/css/bootstrap.css", toCheck.toArray(new BootstrapClass[0]));
    Assert.assertTrue("These classes are missing in bootstrap.css: " + missing, missing.isEmpty());
}

@Test
public void testValueOfMeasureAttributes() {
    Assert.assertEquals(BootstrapClass.COL_1, BootstrapClass.valueOf(new Measure("1", Measure.Unit.SEG), Attributes.extraSmall));
    Assert.assertEquals(BootstrapClass.COL_12, BootstrapClass.valueOf(new Measure("12", Measure.Unit.SEG), Attributes.extraSmall));
    Assert.assertEquals(null, BootstrapClass.valueOf((Measure) null, Attributes.extraSmall));
    Assert.assertEquals(BootstrapClass.COL_MD_5, BootstrapClass.valueOf(new Measure("5", Measure.Unit.SEG), Attributes.medium));
    Assert.assertEquals(BootstrapClass.COL_LG, BootstrapClass.valueOf(Measure.valueOf("*"), Attributes.large));
    Assert.assertEquals(BootstrapClass.COL_XL_AUTO, BootstrapClass.valueOf(Measure.valueOf("auto"), Attributes.extraLarge));
}

@Test
public void testGetRegExpForUndefinedAttributes() {
    String regexp = CheckstyleConfigGenerator.getRegExpForUndefinedAttributes("tc", "textarea", Arrays.asList("attr1", "attr2"));
    Assert.assertEquals("<tc:textarea(\\s+(attr1|attr2|xmlns:\\w*)=\\\"([^\"=<>]*)\\\")*\\s+(?!(attr1|attr2|xmlns:\\w*|\\W))", regexp);
    regexp = ".*" + regexp + ".*";
    Assert.assertFalse("<tc:textarea attr1=\"bla bla\"/>".matches(regexp));
    Assert.assertFalse("<tc:textarea attr2=\"bla bla\"/>".matches(regexp));
    Assert.assertFalse("<tc:textarea attr2=\"bla bla\" attr1=\".....\"/>".matches(regexp));
    Assert.assertTrue("<tc:textarea hallo=\"bla bla\"/>".matches(regexp));
    Assert.assertFalse("<tc:textarea xmlns:f=\"http://java.sun.com/jsf/core\" attr1=\"bla bla\"/>".matches(regexp));
    Assert.assertTrue("<tc:textarea xmlns:f=\"http://java.sun.com/jsf/core\" hallo=\"bla bla\"/>".matches(regexp));
    Assert.assertFalse("<any> <tc:textarea      attr1=\"bla bla\"     /> <any>".matches(regexp));
    Assert.assertFalse("<any> <tc:textarea         attr2=\"bla bla\"  /><any>".matches(regexp));
    Assert.assertFalse("<any> <tc:textarea            attr2=\"bla bla\"    attr1=\".....\"/><any> ".matches(regexp));
    Assert.assertTrue("<any> <tc:textarea        hallo=\"bla bla\"         /> <any> ".matches(regexp));
}
